This PR is an implementation of @reduz's proposal for Drawable Textures in the Godot Engine. Authored primarily by me, with some much appreciated assistance from @clayjohn  and @BastiaanOlij.

See Demo Vid:

https://github.com/user-attachments/assets/95b1f1dc-fa03-4788-b03c-ffad469ede48

Download Demo Project: [drawable-texture-tests.zip](https://github.com/user-attachments/files/22552003/drawable-texture-tests.zip)

The implementation follows Reduz’s specification pretty strictly, with a few departures based on feedback from Rendering Contributor Meetings. Most importantly, we decided to leave implementation of Blit_Polygon functions for a future pull request due to complexity.  We also added a p_material parameter to Blit_Rect & Blit_Rect_Multi on the user exposed resource to allow users to pass their own materials into the resource (if left blank, still defaults to 'default material').

This PR implements:
The Rendering Server API for DrawableTextures 
```cpp
enum TextureDrawableFormat {
   TEXTURE_DRAWABLE_FORMAT_RGBA8,
   TEXTURE_DRAWABLE_FORMAT_RGBA8_SRGB, // Use this if you want to read the result from both 2D (non-hdr) and 3D.
   TEXTURE_DRAWABLE_FORMAT_RGBAH,
   TEXTURE_DRAWABLE_FORMAT_RGBAF,
};

// Create
RID texture_drawable_create(int p_width, int p_height, TextureDrawableFormat p_format, const Color &p_color = Color(1, 1, 1, 1), bool p_with_mipmaps = false);

// Blit a rect
void texture_drawable_blit_rect(const TypedArray<RID> &p_textures, const Rect2i &p_rect, RID p_material, const Color &p_modulate, const TypedArray<RID> &p_source_textures, int p_to_mipmap = 0);

// Utility functions
RID texture_drawable_get_default_material(); // To use with simplified functions in DrawableTexture2D
void texture_drawable_generate_mipmaps(RID p_texture) // Populate the mipmaps for this drawable texture
``` 
The new ShaderType, TextureBlit Shaders
```glsl
shader_type texture_blit
// Optional render modes:
render_mode blend_mix /* default , also available: blend_add, blend_sub, blend_mul */;

uniform sampler2D source_texture : hint_blit_source0;
uniform sampler2D source_texture1 : hint_blit_source1;
// up to 4 sources

void blit() {
     // Read sources and blit
     COLOR0 = texture(source_texture,UV) * MODULATE;
     COLOR1 = texture(source_texture1,UV);
     // up to COLOR3
}
```
And several user-exposed Resource classes to interact with DrawableTextures, most importantly of course, DrawableTexture2D
```cpp
class DrawableTexture2D : public Texture2D {
   enum DrawableFormat {
       DRAWABLE_FORMAT_RGBA8,
       DRAWABLE_FORMAT_RGBA8_SRGB,
       DRAWABLE_FORMAT_RGBAH,
       DRAWABLE_FORMAT_RGBAF,
   };
    void setup(int p_width, int p_height, DrawableFormat p_format, const Color &p_modulate = Color(1, 1, 1, 1), bool p_use_mipmaps = false);
    void blit_rect(const Rect2i p_rect, const Ref<Texture2D> &p_source, const Color &p_modulate = Color(1, 1, 1, 1), int p_mipmap = 0, const Ref<Material> &p_material = Ref<Material>());
    void blit_rect_multi(const Rect2i p_rect, const TypedArray<Texture2D> &p_sources, const TypedArray<DrawableTexture2D> &p_extra_targets, const Color &p_modulate = Color(1, 1, 1, 1), int p_mipmap = 0, const Ref<Material> &p_material = Ref<Material>());

   void generate_mipmaps();
};
```

