- CRIEI UMA NOVA CLASS CHAMADA: GerenciadorDePlaylists.

- O GerenciadorDePlaylists  gera automaticamente uma pasta "playlists" e permite a criação de novas playlists como arquivos .txt individuais. Quando o usuário tenta criar uma playlist com nome repetido, o sistema detecta e notifica sobre a duplicação. Embora ainda não permita a inclusão de músicas nem a exibição de listagens completas, a estrutura central já opera corretamente - cada playlist corresponde a um arquivo distinto, preparado para receber conteúdo nas próximas versões. O gerenciador já executa com eficiência suas funções primárias de registro e prevenção de duplicatas.

import java.io.*;
import java.util.ArrayList;

public class GerenciadorDePlaylists {
    private final String pastaPlaylists = "playlists";
    private final ArrayList<String> playlists = new ArrayList<>();

    public GerenciadorDePlaylists() {
        new File(pastaPlaylists).mkdirs();
    }

    public void criarPlaylist(String nome) {
        try {
            File novaPlaylist = new File(pastaPlaylists, nome + ".txt");
            if (novaPlaylist.createNewFile()) {
                playlists.add(nome);
                System.out.println("✅ Playlist criada!");
            } else {
                System.out.println("⚠️ Playlist já existe!");
            }
        } catch (IOException e) {
            System.out.println("Erro ao criar playlist: " + e.getMessage());
        }
    }
}
